@staticmethod
def _provider_error(status_code: Any, message: str, *, headers: Mapping[str, Any] | None = None, metadata: Mapping[str, Any] | None = None) -> ProviderFailure:
    resolved_status = status_code if isinstance(status_code, int) else None
    retry_after_seconds = None

    if resolved_status == 429:
        # Check metadata for retry_after_seconds
        if metadata and isinstance(metadata, Mapping):
            retry_after_val = metadata.get("retry_after_seconds")
            if isinstance(retry_after_val, (int, float)) and retry_after_val > 0:
                retry_after_seconds = float(retry_after_val)

        # Check headers for Retry-After
        if retry_after_seconds is None and headers and isinstance(headers, Mapping):
            retry_after_val = headers.get("Retry-After") or headers.get("retry-after")
            if isinstance(retry_after_val, (int, float)) and retry_after_val > 0:
                retry_after_seconds = float(retry_after_val)
            elif isinstance(retry_after_val, str):
                try:
                    retry_after_seconds = float(retry_after_val)
                    if retry_after_seconds <= 0:
                        retry_after_seconds = None
                except ValueError:
                    pass

        return ProviderFailure(
            "rate_limit", message, retryable=True, status_code=resolved_status, retry_after_seconds=retry_after_seconds
        )

    retryable = resolved_status is not None and resolved_status >= 500
    return ProviderFailure(
        "provider_5xx" if retryable else "provider_rejected",
        message,
        retryable=retryable,
        status_code=resolved_status,
    )

